// ESP-01: TX=3, RX=4, 115200 бод
#include <SoftwareSerial.h>

// Для ESP-01 стандартный софт-серийный порт может быть нестабилен на 115200, 
// но в рамках решения используем SoftwareSerial.
SoftwareSerial espSerial(4, 3); // RX, TX

void setup() {
  Serial.begin(115200);
  espSerial.begin(115200);
  Serial.println("Готов к ESP-01 обмену");
}

void loop() {
  if (espSerial.available()) {
    Serial.write(espSerial.read());
  }
  if (Serial.available()) {
    espSerial.write(Serial.read());
  }
}
